/* Simplified Chinese for the glossary (the interface language pack; company SOP texts stay in Uzbek) */
var TERMS_ZH = {
  t1: { term: '装箱单 (Packing list)', short: '货物件数与品名清单', def: '由发货方出具的单据：共多少件、每件装什么、重量和尺寸。收货时件数必须与该单据逐一核对。没有装箱单不得收货。', syn: ['PL', 'packing list', '装箱清单'] },
  t2: { term: '发票 (Invoys)', short: '标明货物价值的商业发票', def: '客户或工厂出具的单据：品名、数量和金额。海关申报以该单据为依据填写，因此其中的金额必须与合同一致。', syn: ['Invoice', '商业发票'] },
  t3: { term: '异常记录单', short: '记录不符情况的正式单据', def: '货物、单据或数量出现差异时出具。至少两人签字并附照片。没有异常记录单，事后无法向承运人或工厂索赔。', syn: ['Akt', '事故记录单'] },
  t4: { term: '客户代码', short: '分配给每位客户的唯一编号', def: '客户的所有货物均在该代码下流转。代码在标签、系统和单据上写法必须完全一致。相近的代码不在同一天发放，以免混淆。', syn: ['Kod', '客户编号'] },
  t5: { term: '贴标', short: '在货物上粘贴标签', def: '每一件货物都要贴上写有客户代码和件号的标签。贴完后用扫描枪核对：系统中的代码与标签上的代码必须一致。', syn: ['Markirovka', '打标'] },
  t6: { term: 'WMS', short: '仓库管理系统', def: 'Warehouse Management System——记录仓库中货物存放位置的系统。每一件货物都要录入系统；未录入的货物在仓库中视为「不存在」。', syn: ['仓库系统'] },
  t7: { term: 'TSD 扫描枪', short: '读取条码的手持终端', def: '扫描标签后将数据直接发送到 WMS。相比手工记录可大幅减少差错。', syn: ['Skaner', '手持终端'] },
  t8: { term: '拼箱 (Konsolidatsiya)', short: '把多个客户的货物拼到一车', def: '小批量货物在仓库集货后合并成一个车次。对客户来说运费更低，但要多等待一段时间。', syn: ['集货', '拼车'] },
  t9: { term: '体积 (m³)', short: '货物的体积', def: '长 × 宽 × 高。运费通常按重量与体积中较大者计算——轻抛货按体积计费。', syn: ['CBM', '方数'] },
  t10: { term: '过境 (Tranzit)', short: '经由第三国境内通行', def: '货物在到达最终目的地前要经过其他国家境内。过境期间不得开箱，过境单据需单独办理。', syn: ['Transit'] },
  t11: { term: '报关单', short: '向海关提交的主要单据', def: '载明货物、商品编码、价值和应缴税费。由报关员填写；其中的信息必须与发票和装箱单一致。', syn: ['Deklaratsiya', '海关申报单'] },
  t12: { term: 'HS 编码 (TIF TN)', short: '货物的海关归类编码', def: '每类商品对应一个 10 位编码。编码选错，税率也会算错，并可能被处罚。', syn: ['TN VED', '商品编码'] },
  t13: { term: '报关行', short: '办理海关手续的代理方', def: '以公司名义办理海关单据的持牌机构或专业人员。', syn: ['Broker', '报关代理'] },
  t14: { term: '霍尔果斯', short: '中国—哈萨克斯坦边境口岸', def: '我们大部分货物经该口岸通行。这里可能需要换装并排队——计算时效时务必把这一点算进去。', syn: ['Xorgos', 'Horgos'] },
  t15: { term: '总时效 (Lead time)', short: '从下单到交付的全部时间', def: '不只是在途时间：仓库集货、单据办理、过境和末端派送都算在内。对客户报的正是这个时效。', syn: ['交货周期'] },
  t16: { term: 'SLA', short: '服务水平协议', def: 'Service Level Agreement——公司在响应和交付时效方面的承诺。一旦无法达成 SLA，必须提前告知客户。', syn: ['服务协议'] },
  t17: { term: '价格政策', short: '定价规则', def: '按线路、体量和客户等级确定价格的规则。属内部信息——对客户只报最终价格。', syn: ['Tarif siyosati', '定价规则'] },
  t18: { term: 'EXW / FOB / DAP', short: 'Incoterms——费用与责任的分界', def: '规定卖方与买方各自承担到哪一环节的费用和责任。EXW——由买方从工厂提货；FOB——卖方负责到装运港；DAP——卖方负责到指定目的地。', syn: ['Incoterms', '贸易术语'] }
};

